#include "NativeSSAOContext.h"
#include "Rendering/Backend/NativeWorldDrawSequence.h"
#include <cmath>
#include <charconv>
#include <utility>
namespace rendering {
namespace {void Check(bool x,const char*t){if(!x)throw std::runtime_error(t);}uint64_t nextImage=1,nextFBO=1;uint64_t Next(uint64_t&v){Check(v&&v<UINT64_MAX,"Original SSAO resource identity overflow");return v++;}}
NativeSSAOContext::NativeSSAOContext(NativeSSAORecorder&r,uint32_t m,NativeSSAOEvents e):recorder(r),maxDimension(m),events(std::move(e)){Check(m&&events.state&&events.binding&&events.sourceDrawFrame,"SSAO requires actual renderer/context callbacks");}
NativeSSAOContext::~NativeSSAOContext(){for(auto&[name,cell]:images)if(!cell->deleted&&events.deleted)events.deleted(name);}
std::string NativeSSAOContext::CreateTexture(uint32_t w,uint32_t h,NativeSSAOFormat format,NativeTextureSampling sampling){Check(w&&h&&w<=maxDimension&&h<=maxDimension,"Original SSAO texture exceeds actual native extent");Check((sampling.minFilter==0x2600||sampling.minFilter==0x2601)&&(sampling.magFilter==0x2600||sampling.magFilter==0x2601)&&sampling.wrapS==0x812f&&sampling.wrapT==0x812f,"Original SSAO sampler policy differs");auto im=std::make_shared<NativeSSAOImage>();im->identity=Next(nextImage);im->width=w;im->height=h;im->format=format;im->sampling=sampling;auto cell=std::make_shared<NativeSSAOImageCell>();cell->image=im;std::string name="!nativeSSAO"+std::to_string(im->identity);auto [i,ok]=images.emplace(name,cell);Check(ok,"Duplicate SSAO texture identity");try{if(events.created)events.created(name,cell);}catch(...){images.erase(i);throw;}return name;}
void NativeSSAOContext::DeleteTexture(const std::string&name){auto i=images.find(name);if(i==images.end())return;if(!i->second->deleted&&events.deleted)events.deleted(name);i->second->deleted=true;images.erase(i);}
std::shared_ptr<NativeSSAOFBO>NativeSSAOContext::CreateFBO(const std::string&name){auto i=images.find(name);Check(i!=images.end()&&!i->second->deleted,"Original SSAO color attachment is missing/deleted");auto f=std::make_shared<NativeSSAOFBO>();f->identity=Next(nextFBO);f->color=i->second;fbos.emplace(f->identity,f);return f;}
void NativeSSAOContext::DeleteFBO(const std::shared_ptr<NativeSSAOFBO>&f){if(!f)return;if(target==f)target.reset();f->deleted=true;fbos.erase(f->identity);}
uint64_t NativeSSAOContext::BindFBO(std::shared_ptr<NativeSSAOFBO>f){Check(f&&!f->deleted&&f->color&&!f->color->deleted,"Invalid original SSAO FBO");uint64_t prior=target?target->identity:0;target=std::move(f);return prior;}
void NativeSSAOContext::RestoreFBO(uint64_t name){if(!name){target.reset();return;}auto i=fbos.find(name);Check(i!=fbos.end()&&!i->second->deleted,"SSAO raw FBO restoration names an unknown/deleted object");target=i->second;}
std::shared_ptr<NativeSSAOProgramState>NativeSSAOContext::CreateProgram(NativeSSAOProgram kind,NativeSSAODefines d){ValidateNativeSSAODefines(d);Check(kind==NativeSSAOProgram::TexRect||!d.empty(),"SSAO shader defines missing");auto p=std::make_shared<NativeSSAOProgramState>();p->kind=kind;p->defines=std::move(d);return p;}
void NativeSSAOContext::Activate(std::shared_ptr<NativeSSAOProgramState>p){Check(p&&!p->deleted,"Deleted SSAO program activation");active=std::move(p);}
void NativeSSAOContext::Deactivate(const std::shared_ptr<NativeSSAOProgramState>&p){if(active==p)active.reset();}
void NativeSSAOContext::Finalize(const std::shared_ptr<NativeSSAOProgramState>&p){if(!p)return;Deactivate(p);p->deleted=true;}
void NativeSSAOContext::Uniform(const std::shared_ptr<NativeSSAOProgramState>&p,std::string_view name,std::span<const float>v){Check(p&&!p->deleted,"Deleted SSAO uniform target");for(float x:v)Check(std::isfinite(x),"Nonfinite original SSAO uniform");auto&u=p->uniforms;if(name=="testuniform"){Check(v.size()==1,"SSAO testuniform arity");u.testUniform=v[0];}else if(name=="dir"){Check(v.size()==2,"SSAO dir arity");std::copy(v.begin(),v.end(),u.direction.begin());}else if(name=="strengthMult"){Check(v.size()==1,"SSAO strength arity");u.strength=v[0];}else if(name=="weights"||name=="offsets"){Check(v.size()==size_t(p->defines.at("BLUR_HALF_KERNEL_SIZE")),"SSAO original Gaussian array size differs");std::copy(v.begin(),v.end(),name=="weights"?u.weights.begin():u.offsets.begin());}else if(name=="invProjMatrix"){Check(v.size()==16,"SSAO original inverse projection size differs");std::copy(v.begin(),v.end(),u.inverseProjection.begin());}else if(name.starts_with("samplingKernel[")&&name.ends_with("]")){unsigned i=UINT32_MAX;auto first=name.data()+15,last=name.data()+name.size()-1;auto parsed=std::from_chars(first,last,i);Check(parsed.ec==std::errc{}&&parsed.ptr==last&&i<unsigned(p->defines.at("SSAO_KERNEL_SIZE"))&&v.size()==3,"SSAO original kernel index/arity differs");std::copy(v.begin(),v.end(),u.samplingKernel[i].begin());}else if(name=="uniformparams"){Check(p->kind==NativeSSAOProgram::TexRect&&v.size()==4,"Unexpected original texrect uniform");}else throw std::runtime_error("Unknown original SSAO uniform");}
void NativeSSAOContext::Texture(unsigned unit,const std::string&name){Check(unit<8&&events.bind,"SSAO texture binding outside original sampler slots");events.bind(unit,name);}
void NativeSSAOContext::DisableTexture(unsigned unit){Check(unit<8&&events.disable,"SSAO texture disable outside original sampler slots");events.disable(unit);}
void NativeSSAOContext::Commit(NativeSSAODraw d){Check(recorder.Active(),"SSAO draw outside original PreParticles capture");d.sequence=NextNativeWorldDrawSequence();auto cell=target?target->color:nullptr;std::string name;if(cell){Check(!cell->deleted&&cell->nextGeneration<UINT64_MAX,"Deleted/exhausted SSAO target");auto v=std::make_shared<NativeSSAOImageVersion>();v->image=cell->image;v->generation=cell->nextGeneration;v->sourceDrawFrame=events.sourceDrawFrame();v->producerSequence=d.sequence;d.output=v;d.previous=cell->current;for(auto&[key,value]:images)if(value==cell){name=key;break;}Check(!name.empty(),"SSAO original target texture name lost");}
 auto next=d.output,previous=d.previous;auto cancel=std::make_shared<std::function<void()>>();
 auto rollback=[cell,next,previous,cancel]()noexcept{if(*cancel)(*cancel)();if(cell&&cell->current==next)cell->current=previous;};
 recorder.RecordTransactional(std::move(d),[&]{if(cell&&events.publish)*cancel=events.publish(name,next);if(cell){cell->current=next;++cell->nextGeneration;}},cell?std::function<void()>(std::move(rollback)):std::function<void()>{});
}
void NativeSSAOContext::Draw(std::array<std::array<float,4>,6>vertices,std::shared_ptr<const NativeSSAOTileGeometry>tiles){Check(active&&!active->deleted,"SSAO VAO draw has no actual program");NativeSSAODraw d;d.program=active->kind;d.defines=active->defines;d.uniforms=active->uniforms;d.vertices=vertices;d.tiles=std::move(tiles);auto state=events.state();d.surface=std::move(state.first);d.world=std::move(state.second);d.world.inheritedClipPlane.reset();for(unsigned i=0;i<8;++i){d.inputs[i].actual=events.binding(i);auto object=d.inputs[i].actual.object;if(object&&object->backing)if(auto b=std::dynamic_pointer_cast<const NativeSSAOImageBacking>(object->backing)){d.inputs[i].local=b->version;d.inputs[i].actual={};}}Commit(std::move(d));}
void NativeSSAOContext::Clear(std::array<float,4>color){Check(bool(target),"Private SSAO clear requires its actual color FBO");NativeSSAODraw d;d.clear=true;d.clearColor=color;auto state=events.state();d.surface=std::move(state.first);d.world=std::move(state.second);d.world.inheritedClipPlane.reset();Commit(std::move(d));}
}
